#!/usr/bin/env python3
"""Compile native download UI against the real Android SDK with explicit app boundaries."""
import argparse,hashlib,json,pathlib,subprocess,tempfile
ROOT=pathlib.Path(__file__).resolve().parents[2];HERE=pathlib.Path(__file__).resolve().parent;PROD=ROOT/'app/src/main/java/local/pocketchat'
def main():
 p=argparse.ArgumentParser();p.add_argument('--java-home',type=pathlib.Path,required=True);p.add_argument('--android-jar',type=pathlib.Path,required=True);p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=True)
 names=['DesignDownloads.java','DownloadDisplayCache.java','DownloadCenterActivity.java','DownloadQuery.java','DownloadCollection.java','DownloadCollectionSession.java','DownloadCollectionShare.java','DownloadMetadataValues.java','DownloadTaskRevisions.java','DownloadRowBinding.java','DownloadOwnerLabels.java','DownloadPageWindow.java','DownloadListPolicy.java','DownloadReadGate.java'];inputs=[PROD/n for n in names]+[HERE/'AndroidCompileBoundary.java',pathlib.Path(__file__).resolve()];hashes={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest()for f in inputs}
 with tempfile.TemporaryDirectory(prefix='download-native-api-')as raw:
  temp=pathlib.Path(raw);run=subprocess.run([str(a.java_home/'bin/javac'),'-encoding','UTF-8','-cp',str(a.android_jar),'-d',str(temp/'classes'),*map(str,[f for f in inputs if f.suffix=='.java'])],text=True,capture_output=True,timeout=90);(a.output/'stdout.txt').write_text(run.stdout);(a.output/'stderr.txt').write_text(run.stderr);run.check_returncode();report={'status':'passed','scope':'Native download production sources compiled against actual Android SDK; surrounding app classes are explicit compile-only adapters','productionFiles':names,'androidJarSha256':hashlib.sha256(a.android_jar.read_bytes()).hexdigest(),'sourceFiles':hashes,'actualAndroidExecution':False,'fullAppBuild':False,'executionInputsUnchanged':all(hashlib.sha256((ROOT/n).read_bytes()).hexdigest()==h for n,h in hashes.items())};(a.output/'results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');assert report['executionInputsUnchanged'];print(json.dumps({'status':report['status'],'productionFiles':len(names),'output':str(a.output)}))
if __name__=='__main__':main()
